import { tween, styler } from "popmotion";

const styler = styler(document.querySelector(".box"));
tween({ from: 0, to: 100, duration: 300 }).start(v =>
  styler.set({ x: v })
);

import { animate, spring } from "popmotion";

const ball = document.querySelector(".ball");

animate({
  from: 0,
  to: 300,
  onUpdate: (x) => {
    ball.style.transform = `translateX(${x}px)`;
  },
  transition: spring({ stiffness: 200, damping: 20 }),
});

import { pointer, spring } from "popmotion";

const ball = document.querySelector(".ball");

let x = 0;

pointer({ target: ball })
  .start((event) => {
    if (event.type === "pointerdown") return;

    x += event.movementX;
    ball.style.transform = `translateX(${x}px)`;
  })
  .stop();
